function Cart({ groupedCart, total, placeOrder, clearCart }) {
  return (
    <div style={{ padding: "30px" }}>
      <h1>Your Cart</h1>

      {groupedCart.length === 0 ? (
        <p>Cart is empty</p>
      ) : (
        <>
          {groupedCart.map((item) => (
            <div
              key={item._id}
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                border: "1px solid #ddd",
                padding: "15px",
                marginBottom: "15px",
                borderRadius: "10px",
              }}
            >
              <div>
                <h3>{item.name}</h3>
                <p>
                  ₹{item.price} × {item.qty}
                </p>
              </div>

              <h3>₹{item.price * item.qty}</h3>
            </div>
          ))}

          <h2>Total: ₹{total}</h2>

          <button
            onClick={placeOrder}
            style={{
              padding: "10px 20px",
              marginRight: "10px",
              cursor: "pointer",
            }}
          >
            Place Order
          </button>

          <button
            onClick={clearCart}
            style={{
              padding: "10px 20px",
              cursor: "pointer",
            }}
          >
            Clear Cart
          </button>
        </>
      )}
    </div>
  );
}

export default Cart;
